/** §7.2: registration lag from A-press to first visible effect (message-box clear + char 0 the same tick) - matches press #2's own lag, not press #1's (open question, not re-derived here, see dossier). */
const SENDOUT_TEXT_LAG = 5;
/** §7.3: "BUG CATCHER DESTIN sent" (23 printable chars, 3 spaces) / "out GROVYLE!" (12 printable chars, 1 space) - sText_Trainer1SentOutPkmn, battle_message.c:388. */
export interface BattleSendOutEncounterParams {
  readonly line1: string;
  readonly line2: string;
  readonly textTotal: number;
}

/** BattleSetup-backed encounter identity expressed for the shared send-out printer. */
export function battleSendOutEncounterParams(
  encounter: BattleSceneState["encounter"] = "destin",
  trainerPresentation?: FactoryTrainerPresentation,
): BattleSendOutEncounterParams {
  const presentation = presentationForEncounter(encounter, trainerPresentation);
  const line1 = `${presentation.className} ${presentation.name} sent`;
  const line2 = encounter === "jenson" ? "out KABUTO!" : "out GROVYLE!";
  return { line1, line2, textTotal: line1.length + line2.length };
}
/** §7.4: 3-tick lag from text-complete to the post-text handoff (trainer-pic exit / ball spawn / party-summary despawn all start the same tick). */
const SENDOUT_HANDOFF_LAG = 3;

export function sendOutTextStartTick(pressTick: number): number {
  return pressTick + SENDOUT_TEXT_LAG;
}
export function sendOutHandoffTick(
  pressTick: number,
  encounter: BattleSceneState["encounter"] = "destin",
  trainerPresentation?: FactoryTrainerPresentation,
): number {
  return sendOutTextStartTick(pressTick)
    + battleSendOutEncounterParams(encounter, trainerPresentation).textTotal - 1
    + SENDOUT_HANDOFF_LAG;
}

/** Rebase a later encounter onto Battle 1's proven player-send-out clock. */
export function playerSendOutClock(t: number, handoffTick: number): number {
  return t + (1462 - handoffTick);
}

/** Battle 2's inherited player-controller visual chain becomes visible 45 ticks later. */
export const SUBSEQUENT_BATTLE_PLAYER_VISUAL_DELAY = 45;

export function playerTrainerSendOutClock(t: number, handoffTick: number, encounter: BattleSceneState["encounter"]): number {
  const playerT = playerSendOutClock(t, handoffTick);
  return encounter === "jenson" ? playerT - SUBSEQUENT_BATTLE_PLAYER_VISUAL_DELAY : playerT;
}

