/**
 * The lunge redraw's own ground clip - pixel-confirmed against fresh oracle
 * PNGs (this rung's own bisection, docs/battle-turn-notes.md §39): applying
 * the lunge table's `y2` to the sprite's LOWEST rows (feet) produces a
 * silhouette that doesn't match the oracle at any table index past the
 * first (`x2=-17,y2=2`) - the true render leaves everything at screen
 * `y>=74` exactly as the settled (zero-offset) baseline throughout the
 * whole lunge, regardless of the current `y2` (RAM-plausible: the feet stay
 * grounded while the body/wings lift for the dash). Absolute screen `y`, not
 * sprite-local - doesn't line up with a tile-row boundary (`74-19=55`).
 */
/**
 * The foreground battle terrain preserves the settled field at and below
 * this scanline when an opponent-side sprite is redrawn through the
 * canonical layered scene. QUICK_ATTACK/AERIAL_ACE established the same
 * source-relative cutoff first; FLY's affine-double replacement sprite is
 * subject to that layer too.
 */


/**
 * Erases Pidgeotto's own real-sprite footprint (only the settled tileset's
 * opaque pixels, not the whole bounding box) back to the true field
 * background - `eraseGrovyleFootprint`'s own shape, mirrored for the
 * opponent-side Pidgeotto sprite/corner (both sit in the same opponent-side
 * screen region, `GROVYLE_CORNER`/`PIDGEOTTO_CORNER` both `x=144`).
 */
export function eraseSpriteFootprint(
  fb: Uint8Array,
  tileset: Tileset,
  corner: Readonly<{ x: number; y: number }>,
  maxY: number = Infinity,
  bgPaletteOverride?: RgbColor[][],
): void {
  for (let ty = 0; ty < tileset.rows; ty += 1) {
    for (let tx = 0; tx < tileset.columns; tx += 1) {
      const tile = tileset.tiles[ty * tileset.columns + tx];
      if (!tile) continue;
      for (let py = 0; py < 8; py += 1) {
        for (let px = 0; px < 8; px += 1) {
          if (tile[py * 8 + px] === 0) continue;
          const x = corner.x + tx * 8 + px;
          const y = corner.y + ty * 8 + py;
          if (y >= maxY) continue;
          const bg = healthboxBackgroundColorAt(x, y, bgPaletteOverride);
          if (bg) setPixel(fb, x, y, bg);
        }
      }
    }
  }
}

/** Same tile-grid iteration as `drawSpriteSheet`, but skipping any pixel at screen `y >= maxY` - see `OPPONENT_BATTLE_TERRAIN_VISIBLE_BOTTOM`'s own doc comment for why the lunge needs this. */
function drawSpriteSheetClippedBelow(fb: Uint8Array, tileset: Tileset, palette: RgbColor[], ox: number, oy: number, maxY: number): void {
  for (let ty = 0; ty < tileset.rows; ty += 1) {
    for (let tx = 0; tx < tileset.columns; tx += 1) {
      const tile = tileset.tiles[ty * tileset.columns + tx];
      if (!tile) continue;
      const rowY = oy + ty * 8;
      if (rowY >= maxY) continue;
      for (let px = 0; px < 8; px += 1) {
        for (let py = 0; py < 8; py += 1) {
          const y = rowY + py;
          if (y >= maxY) continue;
          const idx = tile[py * 8 + px]!;
          if (idx === 0) continue;
          const c = palette[idx];
          if (!c) continue;
          setPixel(fb, ox + tx * 8 + px, y, c);
        }
      }
    }
  }
}

/**
 * `blendedTile`'s own target-2 always prefers the plain static field
 * background over whatever's already in `fb` (right for DOUBLE_TEAM's
 * clones, which never overlap another same-priority OBJ) - but QUICK_ATTACK's
 * clones DO overlap the real sprite, and RAM confirms `BLDCNT`'s target-2
 * mask includes OBJ (§36), i.e. on real hardware a semi-transparent OBJ
 * blends against WHATEVER is visually beneath it, sprite or background. So
 * these clones must draw AFTER the real sprite's own opaque redraw and
 * blend against the live `fb` (which already has the real sprite painted in
 * wherever it currently sits), not the static background.
 */
function blendedTileOverFb(fb: Uint8Array, tile: number[], palette: RgbColor[], ox: number, oy: number, eva: number, evb: number): void {
  for (let py = 0; py < 8; py += 1) {
    for (let px = 0; px < 8; px += 1) {
      const idx = tile[py * 8 + px]!;
      if (idx === 0) continue;
      const c = palette[idx];
      if (!c) continue;
      const x = ox + px;
      const y = oy + py;
      if (x < 0 || x >= 240 || y < 0 || y >= 160) continue;
      const o = (y * 240 + x) * 4;
      const tgt2 = { r: fb[o]!, g: fb[o + 1]!, b: fb[o + 2]! };
      fb[o] = blendChannel(c.r, tgt2.r, eva, evb);
      fb[o + 1] = blendChannel(c.g, tgt2.g, eva, evb);
      fb[o + 2] = blendChannel(c.b, tgt2.b, eva, evb);
      fb[o + 3] = 255;
    }
  }
}

/** Same tile-grid iteration as `drawSpriteSheetBlended`, but through `blendedTileOverFb` instead of `blendedTile`. */
export function drawSpriteSheetBlendedOverFb(fb: Uint8Array, tileset: Tileset, palette: RgbColor[], ox: number, oy: number, eva: number, evb: number, maxY: number = Infinity): void {
  for (let ty = 0; ty < tileset.rows; ty += 1) {
    const rowY = oy + ty * 8;
    if (rowY >= maxY) continue;
    for (let tx = 0; tx < tileset.columns; tx += 1) {
      const tile = tileset.tiles[ty * tileset.columns + tx];
      if (!tile) continue;
      if (rowY + 8 <= maxY) {
        blendedTileOverFb(fb, tile, palette, ox + tx * 8, rowY, eva, evb);
        continue;
      }
      for (let py = 0; py < 8; py += 1) {
        const y = rowY + py;
        if (y >= maxY) continue;
        for (let px = 0; px < 8; px += 1) {
          const idx = tile[py * 8 + px]!;
          if (idx === 0) continue;
          const c = palette[idx];
          if (!c) continue;
          const x = ox + tx * 8 + px;
          if (x < 0 || x >= 240 || y < 0 || y >= 160) continue;
          const o = (y * 240 + x) * 4;
          const tgt2 = { r: fb[o]!, g: fb[o + 1]!, b: fb[o + 2]! };
          fb[o] = blendChannel(c.r, tgt2.r, eva, evb);
          fb[o + 1] = blendChannel(c.g, tgt2.g, eva, evb);
          fb[o + 2] = blendChannel(c.b, tgt2.b, eva, evb);
          fb[o + 3] = 255;
        }
      }
    }
  }
}

/** Spite's monbg copy, sampled through the source scanline-HOFS wave. */
function drawSpiteWaveMonBg(
  fb: Uint8Array,
  tileset: Tileset,
  palette: RgbColor[],
  ox: number,
  oy: number,
  pointerAge: number,
  eva: number,
  evb: number,
): void {
  for (let sy = 0; sy < tileset.rows * 8; sy += 1) {
    const screenY = oy + sy;
    const shift = spiteWaveShift(pointerAge, screenY, oy);
    for (let sx = 0; sx < tileset.columns * 8; sx += 1) {
      const tile = tileset.tiles[
        Math.floor(sy / 8) * tileset.columns + Math.floor(sx / 8)
      ];
      const index = tile?.[(sy % 8) * 8 + (sx % 8)] ?? 0;
      const color = palette[index];
      const x = ox + sx - shift;
      if (index === 0 || !color || x < 0 || x >= 240
          || screenY < 0 || screenY >= 160) continue;
      const offset = (screenY * 240 + x) * 4;
      fb[offset] = blendChannel(color.r, fb[offset]!, eva, evb);
      fb[offset + 1] = blendChannel(color.g, fb[offset + 1]!, eva, evb);
      fb[offset + 2] = blendChannel(color.b, fb[offset + 2]!, eva, evb);
      fb[offset + 3] = 255;
    }
  }
}

/**
 * Memento's static battler BG copy after the scanline DMA has supplied the
 * selected BG's per-row VOFS.  The copied tilemap starts at map coordinate
 * zero; the source-owned negative BG offsets therefore place the copy at the
 * battler's ordinary screen position.  Palette zero remains transparent just
 * like the copied mon tiles, while every opaque entry is black and alpha
 * blends over the layer already selected by the PPU.
 */
function drawMementoShadowMonBg(
  fb: Uint8Array,
  tileset: Tileset,
  bg: "BG1" | "BG2",
  bgX: number,
  scanlineVofs: readonly number[],
  win0h: number,
  win0v: number,
  eva: number,
  evb: number,
): void {
  const left = (win0h >>> 8) & 0xff;
  const right = win0h & 0xff;
  const top = (win0v >>> 8) & 0xff;
  const bottom = win0v & 0xff;
  if (left >= right || top >= bottom) return;
  // The retained bilateral display maps prove BG1's first visible copied row
  // is scanline 1, while BG2's CopyValue16Bit path can affect scanline 0.
  // This is a BG/register rule, not a species or age special case.
  const firstScanline = bg === "BG1" ? 1 : 0;
  for (let screenY = Math.max(firstScanline, top); screenY < Math.min(160, bottom); screenY += 1) {
    const sourceY = screenY + (scanlineVofs[screenY] ?? 0);
    if (sourceY < 0 || sourceY >= tileset.rows * 8) continue;
    for (let screenX = Math.max(0, left); screenX < Math.min(240, right); screenX += 1) {
      const sourceX = screenX + bgX;
      if (sourceX < 0 || sourceX >= tileset.columns * 8) continue;
      const tile = tileset.tiles[
        Math.floor(sourceY / 8) * tileset.columns + Math.floor(sourceX / 8)
      ];
      const index = tile?.[(sourceY % 8) * 8 + (sourceX % 8)] ?? 0;
      if (index === 0) continue;
      const offset = (screenY * 240 + screenX) * 4;
      fb[offset] = blendChannel(0, fb[offset]!, eva, evb);
      fb[offset + 1] = blendChannel(0, fb[offset + 1]!, eva, evb);
      fb[offset + 2] = blendChannel(0, fb[offset + 2]!, eva, evb);
      fb[offset + 3] = 255;
    }
  }
}

/** VICE_GRIP's flipped ObjBlend CUT frames against the already-selected BG/OBJ target. */
function drawSpriteSheetFlippedBlendedOverTarget(
  fb: Uint8Array,
  target: Uint8Array,
  tileset: Tileset,
  palette: RgbColor[],
  ox: number,
  oy: number,
  hFlip: boolean,
  vFlip: boolean,
  eva: number,
  evb: number,
): void {
  const width = tileset.columns * 8;
  const height = tileset.rows * 8;
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const sourceX = hFlip ? width - 1 - x : x;
      const sourceY = vFlip ? height - 1 - y : y;
      const tile = tileset.tiles[
        Math.floor(sourceY / 8) * tileset.columns + Math.floor(sourceX / 8)
      ];
      const index = tile?.[(sourceY % 8) * 8 + (sourceX % 8)] ?? 0;
      const color = palette[index];
      const dx = ox + x;
      const dy = oy + y;
      if (index === 0 || !color || dx < 0 || dx >= 240 || dy < 0 || dy >= 160) continue;
      const offset = (dy * 240 + dx) * 4;
      fb[offset] = blendChannel(color.r, target[offset]!, eva, evb);
      fb[offset + 1] = blendChannel(color.g, target[offset + 1]!, eva, evb);
      fb[offset + 2] = blendChannel(color.b, target[offset + 2]!, eva, evb);
      fb[offset + 3] = 255;
    }
  }
}

/**
 * GBA semitransparent-OBJ composition after OAM selection. Competing OBJ
 * pixels are resolved to one winning OBJ layer before blending, so a
 * winning semitransparent OBJ must sample target 2 from the next eligible
 * BG/backdrop pixel, not from a losing OBJ that a sequential painter may
 * already have written into `fb`.
 */
function drawSpriteSheetBlendedOverBackdrop(
  fb: Uint8Array,
  backdrop: Uint8Array,
  tileset: Tileset,
  palette: RgbColor[],
  ox: number,
  oy: number,
  eva: number,
  evb: number,
): void {
  for (let ty = 0; ty < tileset.rows; ty += 1) {
    for (let tx = 0; tx < tileset.columns; tx += 1) {
      const tile = tileset.tiles[ty * tileset.columns + tx];
      if (!tile) continue;
      for (let py = 0; py < 8; py += 1) {
        for (let px = 0; px < 8; px += 1) {
          const idx = tile[py * 8 + px]!;
          if (idx === 0) continue;
          const color = palette[idx];
          if (!color) continue;
          const x = ox + tx * 8 + px;
          const y = oy + ty * 8 + py;
          if (x < 0 || x >= 240 || y < 0 || y >= 160) continue;
          const offset = (y * 240 + x) * 4;
          fb[offset] = blendChannel(color.r, backdrop[offset]!, eva, evb);
          fb[offset + 1] = blendChannel(
            color.g,
            backdrop[offset + 1]!,
            eva,
            evb,
          );
          fb[offset + 2] = blendChannel(
            color.b,
            backdrop[offset + 2]!,
            eva,
            evb,
          );
          fb[offset + 3] = 255;
        }
      }
    }
  }
}

/**
 * ISSUES #32 fix (docs/turn9-shake-notes.md's 2026-07-22 PROBE, "Model F",
 * verified pixel-exact across the whole animated window): the only render
 * ticks where slot 3's second life and slot 4 are simultaneously active,
 * their footprints overlap. RAM (`tools/probe/turn9-clone-oam-dump.json`)
 * shows slot 4 wins that OAM tie unconditionally there - so slot 3 must not
 * be allowed to blend AT ALL under any pixel slot 4's own texel will also
 * cover, else slot 4 ends up blending against slot 3's own already-blended
 * result (a double-blend) instead of the plain post-real framebuffer. This
 * mask records exactly which pixels a sprite instance's texels are opaque
 * at, so slot 3's draw can skip them - same tile-grid walk as
 * `drawSpriteSheetBlendedOverFb`, but recording coverage instead of blending.
 */
export function turn9QuickAttackOpaqueMask(tileset: Tileset, ox: number, oy: number, maxY: number): Uint8Array {
  const mask = new Uint8Array(240 * 160);
  for (let ty = 0; ty < tileset.rows; ty += 1) {
    const rowY = oy + ty * 8;
    if (rowY >= maxY) continue;
    for (let tx = 0; tx < tileset.columns; tx += 1) {
      const tile = tileset.tiles[ty * tileset.columns + tx];
      if (!tile) continue;
      for (let py = 0; py < 8; py += 1) {
        const y = rowY + py;
        if (y < 0 || y >= 160 || y >= maxY) continue;
        for (let px = 0; px < 8; px += 1) {
          if (tile[py * 8 + px] === 0) continue;
          const x = ox + tx * 8 + px;
          if (x < 0 || x >= 240) continue;
          mask[y * 240 + x] = 1;
        }
      }
    }
  }
  return mask;
}

/** Same tile-grid iteration as `drawSpriteSheetBlendedOverFb`, but skipping any pixel already set in `skipMask` (the OAM-tie loser's own suppression, see `turn9QuickAttackOpaqueMask`'s doc comment). */
export function drawSpriteSheetBlendedOverFbSkipping(fb: Uint8Array, tileset: Tileset, palette: RgbColor[], ox: number, oy: number, eva: number, evb: number, maxY: number, skipMask: Uint8Array): void {
  for (let ty = 0; ty < tileset.rows; ty += 1) {
    const rowY = oy + ty * 8;
    if (rowY >= maxY) continue;
    for (let tx = 0; tx < tileset.columns; tx += 1) {
      const tile = tileset.tiles[ty * tileset.columns + tx];
      if (!tile) continue;
      for (let py = 0; py < 8; py += 1) {
        const y = rowY + py;
        if (y < 0 || y >= 160 || y >= maxY) continue;
        for (let px = 0; px < 8; px += 1) {
          const idx = tile[py * 8 + px]!;
          if (idx === 0) continue;
          const x = ox + tx * 8 + px;
          if (x < 0 || x >= 240 || skipMask[y * 240 + x]) continue;
          const c = palette[idx];
          if (!c) continue;
          const o = (y * 240 + x) * 4;
          const tgt2 = { r: fb[o]!, g: fb[o + 1]!, b: fb[o + 2]! };
          fb[o] = blendChannel(c.r, tgt2.r, eva, evb);
          fb[o + 1] = blendChannel(c.g, tgt2.g, eva, evb);
          fb[o + 2] = blendChannel(c.b, tgt2.b, eva, evb);
          fb[o + 3] = 255;
        }
      }
    }
  }
}

